import React, { useEffect } from 'react';
import { useConnectedWallet, useWallet } from '@terra-money/wallet-kit';

function Connect() {
  window.connectedWallet = useConnectedWallet();
  const { connect, disconnect, availableWallets } = useWallet();

  const handleDisconnect = () => {
    disconnect();
    // Dispatch a custom event to notify other parts of the application
    const event = new Event('WalletDisconnected');
    window.dispatchEvent(event);
  };

  const handleConnect = (id) => {
    connect(id);

    // Dispatch a custom event to notify other parts of the application
    const event = new Event('WalletConnected');
    window.dispatchEvent(event);
  };

  return (
    <section>
      {connectedWallet ? (
        <>
          <button id="disconnect-button" className="button-disconnect" onClick={handleDisconnect}>Disconnect</button>
        </>
      ) : (
        availableWallets.map(({ id, isInstalled }) => (
          <button id={`connect-button-${id}`} className={`connect-button-${id}`} onClick={() => handleConnect(id)} disabled={!isInstalled} key={id}>
            Wallet
          </button>
        ))
      )}
    </section>
  );
}

export default Connect;
